    assert MockBoard.check_winner(board) == 1

def test_check_winner_vertical_win():
    board = [[1, 2, 0], [1, 2, 0], [1, 0, 2]]
    assert MockBoard.check_winner(board) == 1

def test_check_winner_diagonal_win():
    board = [[1, 2, 0], [0, 1, 2], [0, 0, 1]]
    assert MockBoard.check_winner(board) == 1

